def next_smallest_palindrome(n: int) -> int:
    s = str(n + 1)
    length = len(s)

    # Helper to check if a string is palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # If all 9's, e.g. 9, 99, 999 -> next palindrome is 11, 101, 1001 respectively
    if set(s) == {'9'}:
        return int('1' + ('0' * (length - 1)) + '1')

    while True:
        if is_palindrome(s):
            return int(s)
        # Construct next palindrome candidate by mirroring left half to right
        half = (length) // 2
        if length % 2 == 0:
            left = s[:half]
            pal = left + left[::-1]
        else:
            left = s[:half+1]
            pal = left + left[:-1][::-1]

        if pal >= s:
            s = pal
        else:
            # increment the middle part and then mirror again
            # For even length, increment left half
            # For odd length, increment left half including middle digit
            if length % 2 == 0:
                left_num = int(left) + 1
                left = str(left_num).zfill(half)
                s = left + left[::-1]
            else:
                left_num = int(left) + 1
                left = str(left_num).zfill(half + 1)
                s = left + left[:-1][::-1]
        # If length changed due to increment (e.g. 999 + 1 = 1000), update length
        length = len(s)

