def permute_string(s):
    def helper(chars):
        if not chars:
            return ['']
        first = chars[0]
        rest_perms = helper(chars[1:])
        result = []
        seen = set()
        for perm in rest_perms:
            for i in range(len(perm) + 1):
                new_perm = perm[:i] + first + perm[i:]
