def anti_shuffle(s):
    res = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == ' ':
            # accumulate consecutive spaces
            start = i
            while i < n and s[i] == ' ':
                i += 1
            res.append(s[start:i])
        else:
            # accumulate a word (consecutive non-space chars)
            start = i
            while i < n and s[i] != ' ':
                i += 1
            word = s[start:i]
            # sort the characters of the word by ASCII
            sorted_word = ''.join(sorted(word))
            res.append(sorted_word)
    return ''.join(res)

